document.getElementById('register_form').addEventListener('submit', async function(e) {
  e.preventDefault(); // Prevent default form submission

  const form = e.target;
  const formData = new FormData(form);
  const csrfToken = page_data.csrf_token;

  // const password = formData.get('password');
  // const confirmPassword = formData.get('confirm_password');

  // // Check if passwords match
  // if (password !== confirmPassword) {
  //   Toastify({
  //     text: "❌ Passwords do not match.",
  //     close: true,
  //     gravity: "top",
  //     position: "center",
  //     stopOnFocus: true,
  //     style: {
  //       background: "var(--primary-color-light)",
  //     }
  //   }).showToast();
  //   return;
  // }

  // Convert form data to JSON
  const data = {};
  formData.forEach((value, key) => {
    data[key] = value;
  });

  try {
    const response = await fetch('/api/method/invento_webshop.api.register.register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-frappe-csrf-token': csrfToken,
      },
      body: JSON.stringify({ doc: data })
    });

    const result = await response.json();

    if (response.ok && result.message) {
      Toastify({
  text: '🎉 Registration sent for approval! If you have any queries, please contact us.',
  close: true,
  gravity: "top",
  position: "center",
  stopOnFocus: true,
  style: {
    background: "var(--primary-color)",
  }
}).showToast();
      form.reset(); 
      // window.location.href = '/profile'
    } else {
         if (result._server_messages) {
              const messages = JSON.parse(result._server_messages);
              const firstMessage = JSON.parse(messages[0]);
              const cleanMessage = firstMessage.message.replace(/<[^>]*>/g, ''); 
              errorMessage = `❌ ${cleanMessage}`;

              Toastify({
                text: errorMessage,
                close: true,
                gravity: "top",
                position: "center",
                stopOnFocus: true,
                style: {
                  background: "var(--primary-color-light)",
                }
              }).showToast();
         }
    }
  } catch (error) {
    console.error('Error:', error);
    Toastify({
      text: '⚠️ An error occurred. Please try again.',
      close: true,
      gravity: "top",
      position: "center",
      stopOnFocus: true,
      style: {
        background: "var(--primary-color-light)",
      }
    }).showToast();
  }
});
